118			return fmt.Errorf("stat %s: %w", srcDir, err)
119		}
120		if !info.IsDir() {
121			return nil
122		}
123		return filepath.Walk(srcDir, func(path string, fi os.FileInfo, walkErr error) error {
124			if walkErr != nil {
125				return walkErr
126			}
127			if fi.IsDir() {
128				return nil
129			}
130			rel, err := filepath.Rel(srcDir, path)
131			if err != nil {
132				return fmt.Errorf("rel: %w", err)
133			}
134			return addFileToZip(zw, path, filepath.Join(archivePrefix, rel))
135		})
