16	func newCheckpointDiffCmd() *cobra.Command {
17		var jsonFlag bool
18	
19		cmd := &cobra.Command{
20			Use:   "diff <checkpoint-a> <checkpoint-b>",
21			Short: "Compare two checkpoints",
22			Long: `Compare two checkpoints by ID and report the delta in files touched,
23	token usage, and session counts.
24	
25	Both arguments must be full 12-character hex checkpoint IDs.
26	
27	Examples:
28	  entire checkpoint diff a3b2c4d5e6f7 b1c2d3e4f5a6
29	  entire checkpoint diff a3b2c4d5e6f7 b1c2d3e4f5a6 --json`,
30			Args: cobra.ExactArgs(2),
31			RunE: func(cmd *cobra.Command, args []string) error {
32				ctx := cmd.Context()
33	
34				aID, err := id.NewCheckpointID(args[0])
35				if err != nil {
36					return fmt.Errorf("invalid checkpoint A: %w", err)
37				}
38				bID, err := id.NewCheckpointID(args[1])
39				if err != nil {
40					return fmt.Errorf("invalid checkpoint B: %w", err)
41				}
42	
43				repo, err := strategy.OpenRepository(ctx)
44				if err != nil {
45					return fmt.Errorf("open repository: %w", err)
46				}
47				store := checkpoint.NewGitStore(repo)
48	
49				a, err := store.ReadCommitted(ctx, aID)
50				if err != nil {
51					return fmt.Errorf("read checkpoint %s: %w", aID, err)
52				}
