54				if err != nil {
55					return fmt.Errorf("read checkpoint %s: %w", bID, err)
56				}
57	
58				d := computeCheckpointDiff(a, b)
59				if jsonFlag {
60					return writeCheckpointDiffJSON(cmd.OutOrStdout(), d)
61				}
62				return writeCheckpointDiffText(cmd.OutOrStdout(), d)
63			},
64		}
