72		B             *checkpoint.CheckpointSummary `json:"-"`
73		AID           string                        `json:"a"`
74		BID           string                        `json:"b"`
75		ASessions     int                           `json:"a_sessions"`
76		BSessions     int                           `json:"b_sessions"`
77		SessionsDelta int                           `json:"sessions_delta"`
78		FilesAdded    []string                      `json:"files_added"`
79		FilesRemoved  []string                      `json:"files_removed"`
80		TokensDelta   tokenDelta                    `json:"tokens_delta"`
81	}
