85		Input      int `json:"input"`
86		Output     int `json:"output"`
87		CacheRead  int `json:"cache_read"`
88		CacheWrite int `json:"cache_write"`
89	}
90	
91	func computeCheckpointDiff(a, b *checkpoint.CheckpointSummary) *checkpointDiff {
92		out := &checkpointDiff{
93			A:             a,
94			B:             b,
95			AID:           a.CheckpointID.String(),
96			BID:           b.CheckpointID.String(),
97			ASessions:     a.CheckpointsCount,
98			BSessions:     b.CheckpointsCount,
99			SessionsDelta: b.CheckpointsCount - a.CheckpointsCount,
100		}
101	
102		aFiles := make(map[string]struct{}, len(a.FilesTouched))
103		for _, f := range a.FilesTouched {
104			aFiles[f] = struct{}{}
105		}
106		bFiles := make(map[string]struct{}, len(b.FilesTouched))
107		for _, f := range b.FilesTouched {
108			bFiles[f] = struct{}{}
109		}
110		for f := range bFiles {
111			if _, ok := aFiles[f]; !ok {
112				out.FilesAdded = append(out.FilesAdded, f)
113			}
114		}
115		for f := range aFiles {
116			if _, ok := bFiles[f]; !ok {
117				out.FilesRemoved = append(out.FilesRemoved, f)
118			}
119		}
120		sort.Strings(out.FilesAdded)
121		sort.Strings(out.FilesRemoved)
122	
123		if a.TokenUsage != nil || b.TokenUsage != nil {
124			var aIn, aOut, aCR, aCW int
125			var bIn, bOut, bCR, bCW int
126			if a.TokenUsage != nil {
127				aIn = a.TokenUsage.InputTokens
128				aOut = a.TokenUsage.OutputTokens
129				aCR = a.TokenUsage.CacheReadTokens
130				aCW = a.TokenUsage.CacheCreationTokens
131			}
132			if b.TokenUsage != nil {
133				bIn = b.TokenUsage.InputTokens
134				bOut = b.TokenUsage.OutputTokens
135				bCR = b.TokenUsage.CacheReadTokens
136				bCW = b.TokenUsage.CacheCreationTokens
137			}
138			out.TokensDelta = tokenDelta{
139				Total:      (bIn + bOut + bCR + bCW) - (aIn + aOut + aCR + aCW),
140				Input:      bIn - aIn,
141				Output:     bOut - aOut,
142				CacheRead:  bCR - aCR,
143				CacheWrite: bCW - aCW,
144			}
145		}
146	
147		return out
148	}
