150	func writeCheckpointDiffText(w io.Writer, d *checkpointDiff) error {
151		var sb strings.Builder
152		fmt.Fprintf(&sb, "Diff: %s → %s\n", d.AID, d.BID)
153		fmt.Fprintf(&sb, "\nSessions:        %+d (%d → %d)\n", d.SessionsDelta, d.ASessions, d.BSessions)
154	
155		sb.WriteString("\nTokens:\n")
156		fmt.Fprintf(&sb, "  total:        %+d\n", d.TokensDelta.Total)
157		fmt.Fprintf(&sb, "  input:        %+d\n", d.TokensDelta.Input)
158		fmt.Fprintf(&sb, "  output:       %+d\n", d.TokensDelta.Output)
159		fmt.Fprintf(&sb, "  cache_read:   %+d\n", d.TokensDelta.CacheRead)
160		fmt.Fprintf(&sb, "  cache_write:  %+d\n", d.TokensDelta.CacheWrite)
161	
162		if len(d.FilesAdded) > 0 {
163			fmt.Fprintf(&sb, "\nFiles added (%d):\n", len(d.FilesAdded))
164			for _, f := range d.FilesAdded {
165				sb.WriteString("  + " + f + "\n")
166			}
167		}
168		if len(d.FilesRemoved) > 0 {
169			fmt.Fprintf(&sb, "\nFiles removed (%d):\n", len(d.FilesRemoved))
170			for _, f := range d.FilesRemoved {
171				sb.WriteString("  - " + f + "\n")
172			}
173		}
174		if len(d.FilesAdded) == 0 && len(d.FilesRemoved) == 0 {
175			sb.WriteString("\nFiles touched: identical set.\n")
176		}
177	
178		_, err := io.WriteString(w, sb.String())
179		return err
180	}
